// Router and page frame (plan 3.1, 6.2).  Page workers do not edit this file: see DEV_GUIDE.md for the contract.
//
// Lifecycle of one navigation, in this order:
//   1 abort the previous requests + clean up the previous page   2 (only if slower than 100 ms) paint the skeleton
//   3 load the page module, its CSS and its data (`needs`)       4 render -> frame (crumbs, eyebrow, h1, lede, context, body, „Следва“)
//   5 set document.title                                         6 hydrate [data-ui] components, call mount(), focus the h1
//   7 scroll to the top (or restore it on Back)                  8 tell the shell (nav aria-current etc.)
//
// URL = state.  /path?per=2026.draft&tab=x&to=blockId&demo=error   (js/loc.js: a path address, or #/path in hash mode; an old #/path link is rewritten to the path)
//   per   period key, written only when it is not the default 2026.law (the URL decides; a link click keeps the session period)
//   to    in-page anchor: scroll + highlight (+ opens an ancestor <details>); changing only `to` does not re-render
//   demo  loading | empty | error | pending | offline: renders that state component on any URL
import { ROUTES, NOT_FOUND, byId, match, href as routeHref, chainOf, GROUPS } from './routes.js';
import { store, DEFAULT_PERIOD, ROLE_SELECTOR } from './store.js';
import * as motion from './ui/motion.js';
import { data, PendingError } from './data.js';
import { html, SafeHtml } from './html.js';
import { parseQuery, buildQuery } from './format.js';
import { breadcrumbs } from './ui/breadcrumbs.js';
import { nextCard } from './ui/next.js';
import { pageSkeleton, emptyState, errorState, pendingState } from './ui/states.js';
import * as share from './share.js';
import { redirect } from './redirects.js';
import { ROOT, HASH, here, hereHref, toHref, internal, isAppHref } from './loc.js';
import * as seo from './seo.js';

export class NotFound extends Error { constructor(msg) { super(msg || 'not found'); this.name = 'NotFound'; } }

const SITE = 'Бюджет на светло';
const DEMOS = ['loading', 'empty', 'error', 'pending', 'offline'];
const RERENDER_KEYS = [...(ROLE_SELECTOR ? ['userType'] : []), 'period', 'unit', 'perPerson', 'leva', 'onlyReal'];     // the role selector is off in V5 (js/store.js ROLE_SELECTOR)
const groupLabel = id => GROUPS.find(g => g.id === id)?.label || '';
const $view = () => document.getElementById('view');

let started = false, applying = false;
let navSeq = 0, abort = null, cur = null, lastHref = '', histK = Date.now(), curK = 0, cleanups = [], readyP = Promise.resolve();
const scrollPos = new Map();
const listeners = new Set();

/* ------------------------------------------------------------------ url helpers */
function parseHash(h) {
  let s = String(h || '').replace(/^#/, '');
  if (/^%2F/i.test(s)) { try { s = decodeURIComponent(s); } catch { /* keep */ } }
  const qi = s.indexOf('?');
  const path = qi < 0 ? s : s.slice(0, qi);
  const query = parseQuery(qi < 0 ? '' : s.slice(qi + 1));
  const segs = path.split('/').filter(Boolean).map(x => { try { return decodeURIComponent(x); } catch { return x; } });
  return { segs, query };
}
const canonHash = (canon, q) => toHref('/' + canon.map(encodeURIComponent).join('/') + buildQuery(q));
function canonQuery(q) {
  const o = { ...q };
  if (o.per && (!store.periodByKey(o.per) || o.per === DEFAULT_PERIOD)) delete o.per;
  if (o.demo && !DEMOS.includes(o.demo)) delete o.demo;
  return o;
}
const sigOf = (route, params, query) => `${route.id}|${JSON.stringify(params)}|${JSON.stringify(Object.entries(query).filter(([k]) => k !== 'to'))}`;
const ensureKey = () => { if (!history.state || !history.state.k) history.replaceState({ k: ++histK }, ''); return history.state.k; };
const saveScroll = () => { if (curK) scrollPos.set(curK, window.scrollY); };
const runCleanups = () => { motion.cleanup(); const c = cleanups; cleanups = []; for (const f of c) { try { f(); } catch (e) { console.error(e); } } };

/* ------------------------------------------------------------------ public helpers (also on ctx) */
export function announce(msg) {
  const el = document.getElementById('live');
  if (!el) return;
  el.textContent = '';
  setTimeout(() => { el.textContent = msg; }, 40);
}

/** go('/prihodi/dds') (or the old '#/prihodi/dds') — in-app navigation (history entry); the same address = scroll to top + refocus the h1 */
export function go(addr, o = {}) {
  let target = internal(addr || '/');
  const { query } = parseHash(target);
  const per = store.get('period');
  if (!query.per && per !== DEFAULT_PERIOD) target += (target.includes('?') ? '&' : '?') + 'per=' + per;
  target = toHref(target);
  if (target === hereHref()) { window.scrollTo(0, 0); $view()?.querySelector('h1')?.focus({ preventScroll: true }); return; }
  saveScroll();
  if (o.replace) history.replaceState({ k: ++histK }, '', target);
  else history.pushState({ k: ++histK }, '', target);
  render('link');
}

/** setQuery({tab:'programi', q:''}, {rerender:false}) — change query params in place (replaceState), '' / null removes a key */
export function setQuery(obj, o = {}) {
  const { segs, query } = parseHash(here());
  const q = { ...query };
  for (const [k, v] of Object.entries(obj || {})) { if (v == null || v === '') delete q[k]; else q[k] = String(v); }
  const m = match(segs);
  const h = canonHash(m ? m.canon : segs, canonQuery(q));
  history.replaceState({ k: ensureKey() }, '', h);
  lastHref = location.href;
  if (cur) { const live = cur.ctx?.query; if (live) { for (const k of Object.keys(live)) delete live[k]; Object.assign(live, parseHash(here()).query); } cur.sig = sigOf(cur.route, cur.params, parseHash(here()).query); }
  if (o.rerender !== false) render('rerender');
}
export const rerender = () => render('rerender');
export const onNavigate = fn => { listeners.add(fn); return () => listeners.delete(fn); };

/* ------------------------------------------------------------------ page css + module + data */
const styleLoaded = new Map();
function loadStyle(name) {
  if (!/^[a-z0-9-]+$/.test(name)) return Promise.resolve();
  if (styleLoaded.has(name)) return styleLoaded.get(name);
  if (document.querySelector(`link[data-page="${name}"]`)) { styleLoaded.set(name, Promise.resolve()); return styleLoaded.get(name); }   // in the prerendered HTML already
  const p = new Promise(res => {
    const l = document.createElement('link');
    l.rel = 'stylesheet';
    l.href = new URL(`css/pages/${name}.css`, ROOT).href;
    l.dataset.page = name;
    l.onload = () => res(); l.onerror = () => res();
    setTimeout(res, 2000);
    document.head.appendChild(l);
  });
  styleLoaded.set(name, p);
  return p;
}
function parseNeeds(mod, ctx) {
  const n = typeof mod.needs === 'function' ? mod.needs(ctx) : mod.needs;
  return (n || []).map(s => { const opt = String(s).endsWith('?'); return { name: opt ? String(s).slice(0, -1) : String(s), opt }; });
}
function makeCtx(route, params, query, o) {
  return {
    route, params, query, data: {}, missing: [], period: store.period, store,
    get core() { return data.get('core'); },
    signal: o.signal, demo: o.demo || null, kind: o.kind || 'link',
    setQuery, rerender, announce, go, href: routeHref,
    notFound() { throw new NotFound(); }
  };
}
/** load module + css + data for a route. Used by the router and by S29 (embed). Throws AbortError when superseded. */
export async function prepare(route, params, query, o = {}) {
  const mod = await import(`./pages/${route.file}.js`);
  await Promise.all((mod.styles || []).map(loadStyle));
  const ctx = makeCtx(route, params, query, o);
  const needs = parseNeeds(mod, ctx);
  const results = await Promise.allSettled(needs.map(n => data.load(n.name, { signal: o.signal })));
  let fail = null;
  needs.forEach((n, i) => {
    const r = results[i];
    if (r.status === 'fulfilled') { ctx.data[n.name] = r.value; return; }
    const e = r.reason;
    if (e && e.name === 'AbortError') throw e;
    ctx.missing.push(n.name);
    if (n.opt) return;
    const kind = e instanceof PendingError ? 'pending' : 'error';
    if (!fail || (kind === 'error' && fail.kind === 'pending')) fail = { kind, err: e, file: n.name };
  });
  return { mod, ctx, fail };
}

/* ------------------------------------------------------------------ view model */
const periodsFor = (route, mod) => mod?.periods ?? route.periods;
function supportsPeriod(route, mod) {
  const p = periodsFor(route, mod);
  return p === 'all' || p === 'none' || !Array.isArray(p) || p.includes(store.get('period'));
}
function nextTarget(id) {
  const r = byId[id];
  if (!r) return null;
  if (r.id === 'S01') return { kicker: 'Начало', title: 'Към началото', text: '', href: routeHref('S01') };
  return { kicker: groupLabel(r.group), title: r.title, text: r.desc, href: routeHref(r.id) };
}
function buildNext(route, mod, ctx) {
  if (route.bare) return '';
  let items;
  try { items = mod?.next ? mod.next(ctx) : route.next; } catch (e) { console.error(e); items = route.next; }
  if (!items || !items.length) return '';
  const cards = items.map(it => (typeof it === 'string' ? nextTarget(it) : it)).filter(Boolean);
  if (!cards.length) return '';
  const [first, ...more] = cards;
  return nextCard({ ...first, more: more.map(m => ({ label: m.title, href: m.href })) });
}
function defaultCrumbs(route, title) {
  if (route.id === 'S01') return [];
  return [{ label: 'Начало', href: routeHref('S01') }, ...chainOf(route).map(r => ({ label: r.title, href: routeHref(r.id) })), { label: title }];
}
function eyebrowFor(route) {
  if (route.bare) return '';
  return route.group === 'util' ? '' : groupLabel(route.group);
}
function contextFor(route, ctx, extra, own) {
  if (route.bare) return '';
  const parts = [];
  if (route.periods !== 'none' && !own) parts.push(html`<span class="ctx-period"><strong>${ctx.period.label}</strong> <span class="muted">· ${ctx.period.desc}</span></span>`);
  if (extra) parts.push(extra);
  if (!parts.length) return '';
  return html`<div class="context">${parts.map(p => html`<span class="ctx-part">${p}</span>`)}</div>`;   // v4: the divider between parts is drawn by CSS and is clipped at the start of a wrapped line, so it never dangles
}
const toHtml = v => (v instanceof SafeHtml ? v : html`${v}`);
const safeCall = (fn, ctx, fallback) => { try { const v = fn(ctx); return v ?? fallback; } catch (e) { if (e instanceof NotFound) throw e; console.error(e); return fallback; } };

/** build the view model {route, view, title, eyebrow, lede, context, body, crumbs, next, mod, ctx} for a location */
async function build(route, params, query, o) {
  const demo = DEMOS.includes(query.demo) ? query.demo : null;
  const base = { route, params, query, demo };
  const ctxLite = { period: store.period };
  const frame = (view, body, extra = {}) => ({
    ...base, view, body, title: route.title, eyebrow: eyebrowFor(route), lede: route.desc,
    context: contextFor(route, ctxLite), crumbs: defaultCrumbs(route, route.title), next: buildNext(route, null, ctxLite), mod: null, ctx: null, ...extra
  });

  if (demo === 'loading') return frame('loading', pageSkeleton());
  if (demo === 'empty') return frame('empty', emptyState({ title: 'Няма какво да покажем тук', text: 'Опитай с друга година или друг изглед.' }));
  if (demo === 'error') return frame('error', errorState());
  if (demo === 'pending') return frame('pending', pendingState({ title: route.title, text: 'Данните съществуват при издателя, още не са извлечени.' }));

  const { mod, ctx, fail } = await prepare(route, params, query, { ...o, demo });
  if (o.seq !== navSeq) throw new DOMException('Aborted', 'AbortError');

  if (!supportsPeriod(route, mod)) {
    const sup = periodsFor(route, mod).map(k => store.periodByKey(k)).filter(Boolean);
    return frame('empty', emptyState({
      title: `Няма данни за ${ctx.period.label} на този екран`,
      text: `Този екран показва ${sup.map(p => p.label).join(' и ')}.`,
      actions: sup.map((p, i) => ({ label: `Покажи ${p.label}`, action: 'set-period', value: p.key, primary: i === 0 }))
    }), { ctx, mod });
  }
  if (fail) {
    return frame(fail.kind, fail.kind === 'pending'
      ? pendingState({ title: 'Тези данни още не са включени', text: 'Данните съществуват при издателя, още не са извлечени.' })
      : errorState(), { ctx, mod });
  }

  let out;
  try {
    if (typeof mod.render !== 'function') throw new Error(`pages/${route.file}.js has no render()`);
    out = await mod.render(ctx);
  } catch (e) {
    if (e instanceof NotFound && route !== NOT_FOUND) return build(NOT_FOUND, { path: o.path || '' }, query, o);
    throw e;
  }
  if (o.seq !== navSeq) throw new DOMException('Aborted', 'AbortError');
  const parts = out && typeof out === 'object' && !(out instanceof SafeHtml) && !Array.isArray(out) ? out : { body: out };
  const title = parts.title ?? safeCall(mod.title || (() => route.title), ctx, route.title);
  const pageCrumbs = mod.crumbs ? safeCall(mod.crumbs, ctx, null) : null;
  return {
    ...base, view: 'ready', mod, ctx, title,
    eyebrow: parts.eyebrow ?? eyebrowFor(route), accent: parts.accent,
    lede: parts.lede ?? (mod.lede ? safeCall(mod.lede, ctx, route.desc) : route.desc),
    // for search and answer engines (js/seo.js): the screen's question and its short answer, both as they read on the screen; a more specific
    // document title where one heading serves several addresses (/prihodi/dds); the screen's own JSON-LD nodes
    question: parts.question ?? (mod.question ? safeCall(typeof mod.question === 'function' ? mod.question : () => mod.question, ctx, '') : ''),
    answer: parts.answer ?? (mod.answer ? safeCall(mod.answer, ctx, '') : ''),
    docTitle: parts.docTitle ?? (mod.docTitle ? safeCall(mod.docTitle, ctx, null) : null),
    schema: parts.schema ?? (mod.schema ? safeCall(mod.schema, ctx, []) : []),
    context: contextFor(route, ctx, parts.context, parts.ownContext),
    body: toHtml(parts.body),
    crumbs: pageCrumbs ? [{ label: 'Начало', href: routeHref('S01') }, ...pageCrumbs] : defaultCrumbs(route, title),
    next: buildNext(route, mod, ctx)
  };
}

/* v4 (СИГМА): one italic crimson word in the heading, as СИГМА's „Къде отиват <em>парите</em> на държавата?“. Only for the route's own static
   title and only where it reads naturally (the list below); a title a page sets itself stays plain, and document.title is always plain. */
const ACCENT = { S01: 'бюджет', S04: 'минути', S06: 'парите', S07: 'парите', S10: 'харчи', S12: 'бюджета', S13: 'вървим',
  S31: 'икономиката', S14: 'бюджетът', S15: 'отчети', S16: 'ново', S17: 'дължим', S18: 'данъци', S20: 'община',
  S24: 'данните', S25: 'данни', S26: 'проекта', S27: 'връзка', S30: 'страница' };
function titleHtml(vm) {
  const t = vm.title, w = vm.accent || (t === vm.route.title ? ACCENT[vm.route.id] : '');       // a page may name its own accent word (parts.accent)
  if (typeof t !== 'string' || !w) return t;
  const i = t.lastIndexOf(w);
  return i < 0 ? t : html`${t.slice(0, i)}<em>${w}</em>${t.slice(i + w.length)}`;
}
function frameHtml(vm) {
  const { route } = vm;
  return html`<article class="page${route.bare ? ' page-bare' : ''}" data-route="${route.id}" data-key="${route.key}" data-view="${vm.view}" data-ready="0" aria-labelledby="page-title">
    ${route.bare ? '' : breadcrumbs(vm.crumbs || [])}
    ${vm.eyebrow ? html`<p class="eyebrow">${vm.eyebrow}</p>` : ''}
    <h1 class="page-title" id="page-title" tabindex="-1">${titleHtml(vm)}</h1>
    ${vm.lede && !route.bare ? html`<p class="lede">${vm.lede}</p>` : ''}
    ${vm.context || ''}
    <div class="page-body" data-fk="body">${vm.body}</div>
    ${vm.next || ''}
  </article>`;
}
const docTitle = vm => (vm.route.id === 'S01' ? `${SITE} · ${vm.title}` : `${vm.docTitle || vm.title} · ${SITE}`);

function paint(vm) {
  document.body.classList.toggle('bare', !!vm.route.bare);
  $view().innerHTML = frameHtml(vm).toString();
  document.title = docTitle(vm);
  $view().removeAttribute('aria-busy');
  seo.apply(vm, docTitle(vm));                                   // description, canonical, social cards and JSON-LD of the screen (js/seo.js)
}

/* ------------------------------------------------------------------ hydrate: [data-ui="name"] -> js/ui/name.js mount(el, ctx) */
export async function hydrate(root, ctx, sink = cleanups) {
  const todo = new Map();
  for (const el of root.querySelectorAll('[data-ui]')) {
    if (el.dataset.hydrated) continue;
    el.dataset.hydrated = '1';
    const n = el.dataset.ui;
    if (!/^[a-z0-9-]+$/.test(n)) continue;
    if (!todo.has(n)) todo.set(n, []);
    todo.get(n).push(el);
  }
  await Promise.all([...todo].map(async ([name, els]) => {
    let m;
    try { m = await import(`./ui/${name}.js`); } catch (e) { console.error(`[ui] cannot load ui/${name}.js`, e); return; }
    if (typeof m.mount !== 'function') return;
    for (const el of els) {
      try { const c = await m.mount(el, ctx); if (typeof c === 'function') sink.push(c); } catch (e) { console.error(`[ui/${name}] mount failed`, e); }
    }
  }));
}

/* ------------------------------------------------------------------ in-page anchors (?to=id) */
/** a target inside a hidden tab panel: show that panel and sync its tab (independent of the tabs' own listeners, which may not be mounted yet) */
function revealTabs(el) {
  for (let p = el.closest('[role="tabpanel"]'); p; p = p.parentElement?.closest('[role="tabpanel"]')) {
    if (!p.hidden) continue;
    const host = p.parentElement;
    host.querySelectorAll(':scope > [role="tabpanel"]').forEach(x => { x.hidden = x !== p; });
    host.querySelectorAll(':scope > .tab-list [role="tab"]').forEach(t => {
      const on = t.getAttribute('aria-controls') === p.id;
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
    });
  }
}
/** a target inside the view of a list / map / pie switch (ui/treemap-list.js) that is not shown: switch to that view, as a visitor's own choice */
function revealViews(el) {
  for (let t = el.closest('[data-ui="treemap-list"]'); t; t = t.parentElement?.closest('[data-ui="treemap-list"]')) {
    const pane = ['list', 'map', 'pie'].find(v => { const p = t.querySelector(`:scope > .tmap-${v}`); return p && p.contains(el); });
    if (!pane || t.dataset.view === pane) continue;
    t.dataset.view = pane;
    t.dataset.explicit = '1';
    t.querySelectorAll('.tmap-bar input[type="radio"]').forEach(r => { r.checked = r.value === pane; });
  }
}
function handleTo(id) {
  if (!id) return;
  const el = document.getElementById(id);
  if (!el) return;
  for (let p = el.parentElement; p; p = p.parentElement) if (p.tagName === 'DETAILS') p.open = true;
  if (el.tagName === 'DETAILS') el.open = true;
  revealTabs(el);
  revealViews(el);
  el.scrollIntoView({ block: 'start' });
  el.classList.remove('hl'); void el.offsetWidth; el.classList.add('hl');
  setTimeout(() => el.classList.remove('hl'), 2600);
  if (!el.matches('a,button,input,select,textarea,[tabindex]')) el.setAttribute('tabindex', '-1');
  el.focus({ preventScroll: true });
}

/* ------------------------------------------------------------------ the render pipeline */
const focusKey = () => {
  const a = document.activeElement, v = $view();
  if (!a || a === document.body || !v || !v.contains(a)) return null;
  if (a.id) return '#' + CSS.escape(a.id);
  if (a.dataset.fk) return `[data-fk="${CSS.escape(a.dataset.fk)}"]`;
  return null;
};

async function render(kind) {
  const raw = parseHash(here());
  const red = redirect(raw.segs, raw.query);           // an old address → the matching new screen, context kept (js/redirects.js)
  if (red) { raw.segs = red.segs; raw.query = red.query; }
  const m = match(raw.segs);
  const route = m ? m.route : NOT_FOUND;
  const params = m ? m.params : { path: raw.segs.join('/') };
  const query = canonQuery(raw.query);
  const canon = m ? m.canon : raw.segs;
  const want = canonHash(canon, query);
  if (want !== hereHref() || (!HASH && location.hash.startsWith('#/'))) history.replaceState(history.state || { k: ++histK }, '', want);   // path mode: an old #/x link becomes /x
  const k = ensureKey();
  lastHref = location.href;

  // only the in-page anchor changed: no re-render. Only while no other navigation is in flight (cur.seq === navSeq): when a link was
  // followed and Back came before the new screen was built, Back must supersede that build, or the late screen would paint over the old URL
  const sig = sigOf(route, params, query);
  if (cur && cur.ok && cur.sig === sig && cur.seq === navSeq && kind !== 'rerender' && kind !== 'load') {
    if (kind !== 'pop') saveScroll();
    curK = k;
    cur.query = query;
    if (query.to) handleTo(query.to);
    else if (kind === 'pop' && scrollPos.has(k)) window.scrollTo(0, scrollPos.get(k));
    else window.scrollTo(0, 0);
    return;
  }

  const seq = ++navSeq;
  if (abort) abort.abort();
  abort = new AbortController();
  const signal = abort.signal;
  if (kind !== 'load' && cur) saveScroll();
  const fk = kind === 'rerender' ? focusKey() : null;
  const keepY = kind === 'rerender' ? window.scrollY : 0;
  runCleanups();
  share.reset(route);
  curK = k;

  applying = true;
  try { store.set('period', query.per && store.periodByKey(query.per) ? query.per : DEFAULT_PERIOD); } finally { applying = false; }

  // the first render over a prerendered page (tools/site/build.py): its HTML is already the screen, so no skeleton in between and no rise-in or count-up of what is already shown
  // (dropStalePrerender has taken the mark off an HTML that is the screen of another address)
  const pre = kind === 'load' && document.documentElement.hasAttribute('data-prerendered');
  document.documentElement.removeAttribute('data-prerendered');
  const timer = kind === 'rerender' || pre ? 0 : setTimeout(() => {
    if (seq !== navSeq) return;
    paint({ route, params, query, view: 'loading', title: route.title, eyebrow: eyebrowFor(route), lede: route.desc, body: pageSkeleton(), crumbs: defaultCrumbs(route, route.title), context: '', next: '' });
  }, 100);
  $view()?.setAttribute('aria-busy', 'true');

  let vm;
  try {
    vm = await build(route, params, query, { signal, kind, seq, path: raw.segs.join('/') });
    if (seq !== navSeq) return;
  } catch (e) {
    if (e?.name === 'AbortError' || seq !== navSeq) return;
    console.error(e);
    const title = route.title;
    vm = { route, params, query, demo: null, view: 'error', title, eyebrow: eyebrowFor(route), lede: '', body: errorState(), crumbs: defaultCrumbs(route, title), context: '', next: '', mod: null, ctx: null };
  } finally { clearTimeout(timer); }

  paint(vm);
  cur = { route: vm.route, params: vm.params, query, sig: sigOf(vm.route, vm.params, query), ok: vm.view === 'ready' || vm.view === 'loading' || vm.view === 'empty' || vm.view === 'pending', vm, ctx: vm.ctx, kind, seq };
  for (const f of listeners) { try { f({ route: vm.route, params: vm.params, query, demo: vm.demo, kind, view: vm.view, title: vm.title }); } catch (e) { console.error(e); } }

  const article = $view().querySelector('article.page');
  const h1 = article.querySelector('h1');
  const applyScroll = () => {
    if (kind === 'rerender') window.scrollTo(0, keepY);
    else if (query.to) handleTo(query.to);
    else if (kind === 'pop' && scrollPos.has(k)) window.scrollTo(0, scrollPos.get(k));
    else window.scrollTo(0, 0);
  };
  applyScroll();
  if (!pre) motion.enter(article, kind);                         // V6: the screen rises in; blocks further down appear on scroll (nothing on a 'rerender'; off for reduced motion)
  if (kind === 'rerender') { if (fk) document.querySelector(fk)?.focus({ preventScroll: true }); }
  else if (kind !== 'load' && !query.to) h1.focus({ preventScroll: true });

  // hydrate + mount
  const own = [];
  readyP = (async () => {
    try {
      if (vm.ctx) {
        await hydrate(article, vm.ctx, own);
        if (vm.mod?.mount && vm.view === 'ready') {
          const c = await vm.mod.mount(article.querySelector('.page-body'), vm.ctx);
          if (typeof c === 'function') own.push(c);
        }
      } else await hydrate(article, { route: vm.route, params: vm.params, query, data: {}, missing: [], period: store.period, store, setQuery, rerender, announce, go }, own);
    } catch (e) { console.error(e); }
    if (seq !== navSeq) { for (const f of own) { try { f(); } catch (e) { console.error(e); } } return; }
    cleanups.push(...own);
    if (article.querySelector('[data-gl-scan]')) await import('./glossary.js').then(m => m.scan?.(article)).catch(e => console.error('[glossary] scan failed', e));   // before data-ready: a ready screen has its glossary links
    await import('./ui/png.js').then(m => m.scan?.(article)).catch(e => console.error('[png] scan failed', e));   // „PNG“ button on every statistic
    if (seq !== navSeq) return;
    if (kind === 'pop' || query.to || kind === 'load') applyScroll();
    if (!pre) motion.scan(article);                               // bars fill and numbers count when they come into view
    article.dataset.ready = '1';
  })();
  await readyP;
}

/* ------------------------------------------------------------------ events */
const noFragment = h => h.split('#')[0];
function onLocation(kind) {
  // path mode: when only a plain #fragment changed (a link to #x, or Back from it), the browser scrolls to it. Chrome fires popstate as well
  // as hashchange for it, so both are ignored; a render would take the screen back to the top
  if (!HASH && !location.hash.startsWith('#/') && noFragment(location.href) === noFragment(lastHref)) { lastHref = location.href; return; }
  if (location.href !== lastHref) render(kind);
}

function onClick(e) {
  if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const a = e.target.closest && e.target.closest('a[href]');
  if (!a || (a.getAttribute('target') || '_self') !== '_self' || a.hasAttribute('download')) return;     // getAttribute: an SVG <a> (the map) has an object as .target
  const h = a.getAttribute('href');
  if (h === '#main') { e.preventDefault(); const mn = document.getElementById('main'); mn?.focus({ preventScroll: false }); return; }
  if (!isAppHref(h)) return;
  e.preventDefault();
  if (h.startsWith('#')) { go(h); return; }
  const u = new URL(h, location.href);
  go(internal(u.pathname) + u.search);
}

function onStore(key) {
  if (applying || !started || !RERENDER_KEYS.includes(key)) return;
  if (key === 'period') {
    const per = store.get('period');
    setQuery({ per: per === DEFAULT_PERIOD ? null : per }, { rerender: false });
  }
  clearTimeout(onStore.t);
  onStore.t = setTimeout(() => {
    render('rerender');
    const v = store.get(key);
    const msg = {
      period: `Показваме ${store.period.label}`,
      userType: `Изглед за: ${store.userTypeInfo.label}`,
      unit: v === 'pct' ? 'Показваме в проценти' : 'Показваме в евро',
      perPerson: `На човек: ${v ? 'включено' : 'изключено'}`,
      leva: `Сумите и в лева: ${v ? 'включено' : 'изключено'}`,
      onlyReal: `Само официални данни: ${v ? 'включено' : 'изключено'}`
    }[key];
    if (msg) announce(msg);
  }, 0);
}

/** The prerendered HTML (tools/site/build.py) is the screen of one address, written in data-prerendered. When the page opens under
 *  another one (an old link /#/prihodi/dds loads the HTML of /; a screen without its own file gets 404.html), that text and its numbers
 *  must not stand under the new address while the core data loads: main.js calls this before it waits, and the view stays empty and
 *  busy until the router paints the screen. */
export function dropStalePrerender() {
  const doc = document.documentElement, at = doc.getAttribute('data-prerendered');
  if (at === null) return;
  const raw = parseHash(here());
  const red = redirect(raw.segs, raw.query);
  if (red) { raw.segs = red.segs; raw.query = red.query; }
  const m = match(raw.segs);
  const want = canonHash(m ? m.canon : raw.segs, canonQuery(raw.query));
  if (at === '404' ? !m : at === want && !location.hash.startsWith('#/')) return;
  doc.removeAttribute('data-prerendered');
  const v = $view();
  if (v) { v.replaceChildren(); v.setAttribute('aria-busy', 'true'); }
}

export const router = {
  start() {
    if (started) return readyP;
    started = true;
    try { history.scrollRestoration = 'manual'; } catch { /* old browsers */ }
    window.addEventListener('popstate', () => onLocation('pop'));
    window.addEventListener('hashchange', () => onLocation('hash'));
    document.addEventListener('click', onClick);
    store.subscribe(onStore);
    return render('load');
  },
  go, setQuery, rerender, announce, onNavigate, hydrate, prepare, NotFound,
  parseHash, href: routeHref,
  get current() { return cur; },
  /** the periods the current screen supports: 'all' | 'none' | ['2026.draft', …] (the shell uses it for the period switch) */
  get periods() { return cur ? periodsFor(cur.route, cur.vm && cur.vm.mod) : 'all'; },
  get ready() { return readyP; },
  routes: ROUTES
};
